function humanitiesApplicationQuestion(subject,title){const chinese=subject==='國文';const rules=chinese?[
  [/字音|字形|字詞|詞義|成語/,['句中「走馬看花」最接近哪個意思？',['快速瀏覽','騎馬賞花','細看花朵','停止前進'],0,'成語要依整體語境判讀，不能逐字拆開猜。']],
  [/文言|古典|國學/,['閱讀文言句子時，第一步最可靠的是？',['逐字硬譯','找人物、動作與轉折，再補語意','只背作者年代','忽略虛詞'],1,'先建立誰做什麼，再處理省略、倒裝與古今異義。']],
  [/修辭|抒情|詩歌/,['「風在窗外唱歌」最主要使用何種修辭？',['擬人','借代','排比','設問'],0,'把無生命的風寫成會唱歌，屬於擬人；還要說明它營造的感受。']],
  [/議論|論證/,['文章主張「應減少一次性用品」，哪一項最能支持主張？',['可查證的垃圾量資料','重複主張三次','無關的故事','作者心情'],0,'議論須用可檢查的理由或證據支持主張。']],
  [/說明|圖表|資料/,['閱讀圖表型說明文前，應優先確認？',['標題、單位與資料來源','顏色好不好看','作者名字長短','自己的印象'],0,'圖表的標題、單位與資料範圍決定可否正確比較。']],
  [/跨文本|推論|閱讀策略/,['兩篇文章觀點不同時，最恰當的作法是？',['比較各自的主張與證據','只選自己喜歡的','只看標題','把兩文混成一句'],0,'跨文本要分別找觀點與證據，再比較共同與差異。']],
  [/寫作|組織|表達/,['一段文章要表達「珍惜水資源」，最佳開頭是？',['先提出中心句，再用例子支持','只列標點','先寫結論以外內容','不分段'],0,'中心句先讓讀者知道段落主旨，細節再具體支持。']],
  [/記敘/,['記敘文理解事件轉折時，最有用的線索是？',['人物、事件、時間與感受變化','字數','紙張顏色','作者生日'],0,'以事件順序與人物感受重建內容，才能判讀轉折。']]]:[
  [/臺灣的自然|地圖|地理資訊|區域|世界區域/,['地圖顯示一地降雨量，判讀前最重要的是？',['看圖例、單位、方向與時間','只看顏色深淺','只記地名','忽略比例尺'],0,'地圖符號與單位是資料證據；先確認它們才能比較空間差異。']],
  [/人口|產業|資源|環境|全球化|永續/,['工業區接近港口與交通節點，最合理原因是？',['降低運輸成本並連結市場','氣溫一定最低','人口一定最少','沒有政策影響'],0,'產業區位通常要綜合資源、交通、市場、勞力與政策。']],
  [/史前|荷西|鄭氏|清代|開港|近代|現代臺灣|中國|世界|歷史/,['理解一項歷史事件的影響，最適合的做法是？',['連結背景、事件、不同角色與後續改變','只背年份','只看人物姓名','忽略時間先後'],0,'歷史判讀要用因果與時序連結，而非孤立名詞。']],
  [/法律|權利|民主|政府|公共|社區|市場|金融|經濟|社會生活/,['討論社區垃圾處理時，哪一項屬於公共事務？',['需要共同規則與資源分配','一個人的午餐選擇','私人日記','個人興趣'],0,'公共事務影響多數人，需透過制度、參與與資源協調處理。']]
];const matched=rules.find(([pattern])=>pattern.test(title));const row=matched?.[1];return row?{kind:chinese?'國文文本判讀':'社會資料／制度判讀',question:row[0],answers:row[1],correct:row[2],explanation:row[3],tip:chinese?'先圈文本中的關鍵詞句，再說出它如何支持答案；不要只靠熟悉的名詞。':'先定位時間、空間、角色與制度，再以資料證據連結原因與影響。'}:null;}
function englishApplicationQuestion(title){const data={
  '自我介紹與人稱代名詞':['Amy and I are classmates. ___ study together.',['We','They','He','It'],0,'Amy 和 I 合起來是第一人稱複數，所以用 We。'],
  '日常作息與現在簡單式':['Tom ___ breakfast at 7 every day.',['have','has','is having','had'],1,'every day 表習慣，Tom 是第三人稱單數，用 has。'],
  '正在發生與現在進行式':['Look! The bus ___.',['comes','is coming','came','will come'],1,'Look! 表示眼前正在發生，使用 be＋V-ing。'],
  '名詞、冠詞與數量':['There ___ some water in the bottle.',['is','are','be','am'],0,'water 不可數，搭配單數 be 動詞 is。'],
  '地點與介系詞':['The library is ___ the bank and the park.',['between','at','from','for'],0,'兩個地點之間用 between A and B。'],
  '問句與簡答':['___ your sister like music?',['Do','Does','Is','Are'],1,'your sister 為第三人稱單數，一般動詞問句用 Does。'],
  '過去式與時間線':['Yesterday, we ___ a movie.',['watch','watches','watched','are watching'],2,'Yesterday 是已完成的過去時間，規則動詞加 -ed。'],
  '比較級與最高級':['This bag is ___ than that one.',['heavy','heavier','heaviest','more heavy'],1,'兩個物品比較用比較級；heavy 改 y 為 i 加 -er。'],
  '未來計畫與 be going to':['It is very cloudy. It ___ rain.',['is going to','went to','has to','was'],0,'眼前有明顯徵兆的預測可用 be going to。'],
  '情態助動詞':['You ___ wear a helmet when riding a bike.',['should','shoulds','should to','are should'],0,'情態助動詞後面接原形動詞 wear。'],
  '生活情境閱讀':['A sign says “No food or drinks.” What should you do?',['Eat quietly','Bring a drink','Keep food outside','Ask for a menu'],2,'公告明確禁止食物與飲料，答案要回到文字證據。'],
  '短文寫作':['Which sentence is the best topic sentence for a paragraph about a pet?',['My dog is special to me.','Because I feed it.','And it is brown.','At seven o’clock.'],0,'主題句要先概括段落中心，其他句子可作細節支持。'],
  '過去式':['Last weekend, Mia ___ her grandmother.',['visit','visits','visited','is visiting'],2,'last weekend 是過去時間，規則動詞用 visited。'],
  '比較級':['A train is usually ___ than a bus.',['fast','faster','fastest','more faster'],1,'兩者比較用 faster，不能同時用 more 和 -er。'],
  '未來式':['I think it ___ sunny tomorrow.',['will be','was','is being','has been'],0,'對未來的預測常用 will＋原形。'],
  '不定詞與動名詞':['She enjoys ___ comic books.',['read','to read','reading','reads'],2,'enjoy 後接 V-ing，reading 是動名詞。'],
  '連接詞':['I was tired, ___ I finished my homework.',['but','because','so','if'],0,'前後是轉折：雖然累，仍完成作業，用 but。'],
  '情態助動詞':['You ___ not use your phone during the test.',['must','must to','are must','musts'],0,'must 表規定，後接原形 use。'],
  '被動語態入門':['The cake ___ by my mother yesterday.',['made','was made','is making','makes'],1,'蛋糕承受製作動作，且是過去，使用 was made。'],
  '閱讀圖表':['A timetable shows the last bus leaves at 9:30. What must you do?',['Arrive after 9:30','Get to the stop before 9:30','Wait until midnight','Ignore the time'],1,'從表格找最後一班的時間，再依限制做決定。'],
  '情境對話':['“Could you show me the way to the station?” Best response?',['Sure. Go straight and turn left.','I went yesterday.','The station shows.','No way is a noun.'],0,'問路時應給出有方向性的禮貌回應。'],
  '段落寫作':['Which connector best shows a result?',['therefore','however','although','because of'],0,'therefore 引出前述原因造成的結果。'],
  '現在完成式':['I ___ my homework already.',['finish','finished','have finished','am finish'],2,'already 與完成後的現在狀態，常用 have＋p.p.。'],
  '被動語態':['English ___ in many countries.',['speaks','is spoken','is speaking','spoke'],1,'English 是被使用的語言，現在式被動為 is spoken。'],
  '關係子句':['The boy ___ is wearing a cap is my cousin.',['who','which','where','when'],0,'先行詞是人且子句缺主詞，用 who。'],
  '分詞與長句':['The girl ___ by the window is my friend.',['sit','sits','sitting','sat'],2,'現在分詞 sitting 用來補充說明正在進行的動作。'],
  '篇章連接':['It rained heavily; ___, the game was canceled.',['therefore','however','for example','first'],0,'後句是前句造成的結果，用 therefore。'],
  '推論閱讀':['A passage says Ben took an umbrella and wore boots. What can you infer?',['It may be rainy','It is very hot','He is swimming','He is at a concert'],0,'雨傘與雨靴是文本線索，只能作合理而非絕對的推論。'],
  '圖表與公告':['A museum notice says “Closed on Mondays.” Which visit is possible?',['Monday morning','Monday afternoon','Tuesday morning','Every Monday'],2,'公告限制星期一，星期二可參觀。'],
  '會考寫作':['寫作題要求提出看法並舉例，第一步應做什麼？',['確認任務、立場與兩個可支持的例子','先背一篇文章','只寫結尾','忽略圖片'],0,'先拆解題目任務，決定立場與例證，才能完整回應。']
};const row=data[title];return row?{kind:'英文生活情境',question:row[0],answers:row[1],correct:row[2],explanation:row[3],tip:'先圈出人物、時間與溝通目的；再檢查動詞結構、連接詞或公告限制是否完整符合句意。'}:null;}
function officialPastExamQuestion(subject,title){const key=`${subject}:${title}`,data={
  '數學:二元一次聯立方程式':['115 年國中教育會考｜數學第 1 題','解聯立方程式 x＋2y＝5、2x−2y＝1，x 值為何？',['−4','−2','2','4'],2,'兩式相加先消去 y：3x＝6，所以 x＝2。這是官方 115 年數學第 1 題，本站加入逐步消去法說明。'],
  '數學:平方根':['115 年國中教育會考｜數學第 3 題','若 √504 的最簡根式為 a√b，a＋b 為何？',['13','19','20','50'],2,'504＝36×14，所以 √504＝6√14，a＋b＝20；但原題排版中的 a、b 需依題本符號判讀，請先完整寫出最簡根式。'],
  '數學:機率模型':['115 年國中教育會考｜數學第 4 題','甲袋有 2、3、4；乙袋有 3、4、5，各抽一球時，哪個總和的機率最大？',['6','7','8','9'],1,'列出九個等可能配對後，總和 7 出現 3 次，機率最大。'],
  '數學:科學記號':['115 年國中教育會考｜數學第 8 題','培養皿細菌量分別以 4.4×10⁵、7.3×10⁶、5.4×10⁷ 表示；比較區域大小時，首要比較什麼？',['只比較首數','先比較 10 的指數，再比較首數','只比較單位','直接相加'],1,'科學記號比較大小先比 10 的指數；指數相同才比較首數。此題是官方 115 年數學第 8 題的核心判讀方式。'],
  '數學:一元二次方程式':['115 年國中教育會考｜數學第 9 題','2x(x＋7)−10(x＋7)＝0，最先應採取哪一步？',['展開全部','提出共同因式 (x＋7)','兩邊同加 10','直接除以 x'],1,'兩項都有 (x＋7)，先提公因式得 (x＋7)(2x−10)=0，再用零乘積性質。'],
  '數學:二次函數':['115 年國中教育會考｜數學第 14 題','y＝−(x＋5)²−20 的值域上界為何？',['−20','−15','0','25'],0,'平方項最小為 0，且前面是負號，因此 y 最大為 −20；這是 115 年數學第 14 題的圖形判讀核心。'],
  '數學:二元一次方程式的圖形':['115 年國中教育會考｜數學第 13 題','通過 (−3,−1) 且與 x 軸平行的直線方程式為何？',['x＝−3','y＝−3','x＝−1','y＝−1'],3,'與 x 軸平行代表 y 固定；通過點的 y 是 −1，所以 y＝−1。']
  ,'數學:多項式運算':['114 年國中教育會考｜數學第 2 題','計算 (5x²−2x)−(4−3x)，結果為何？',['5x²−3x','5x²＋x−4','5x²−5x＋4','5x²−5x−4'],1,'減去括號內的整式時，4 與 −3x 都必須變號：5x²−2x−4＋3x＝5x²＋x−4。']
  ,'數學:最大公因數與最小公倍數':['114 年國中教育會考｜數學第 18 題','已知 a、b 的最大公因數為 11、最小公倍數為 88。加入正整數 c 後，三數的最大公因數可能比 11 大、最小公倍數可能比 88 小嗎？',['兩者皆可能','兩者皆不可能','只有最大公因數可能','只有最小公倍數可能'],1,'三數的公因數必同時整除 a、b，所以不能超過兩數的最大公因數 11；三數的公倍數也必是 a、b 的公倍數，所以不能小於 88。']
  ,'數學:二次函數應用':['114 年國中教育會考｜數學第 21 題','將 y＝−(x＋7)²＋12 的圖形向右平移 10 單位時，與 y 軸交點的高度如何變化？',['持續向下','持續向上','先向下再向上','先向上再向下'],3,'平移 t 單位後，y 軸交點高度為 −(7−t)²＋12；t 由 0 到 10 時先接近頂點 t＝7 而上升，再離開頂點而下降。']
  ,'自然:細胞的構造':['115 年國中教育會考｜自然第 6 題','顯微鏡下觀察斑馬魚幼魚的灰色斑塊；依大小尺度判斷，最可能是？',['一個血紅素蛋白','一個病毒','一個粒線體','一個細胞'],3,'細胞尺度遠大於蛋白質、病毒與多數胞器；官方題以圖中尺度對照檢查學生能否判讀大小。']
  ,'自然:電與能量':['115 年國中教育會考｜自然第 7 題','分流電路中 A1＝500 mA、A2＝300 mA，依電流守恆，A3 最接近？',['200 mA','500 mA','800 mA','1000 mA'],0,'在分岔處，總電流等於各支路電流和；500−300＝200 mA。']
  ,'自然:板塊與地質':['115 年國中教育會考｜自然第 8 題','地震預警顯示「震度 4 級將在 13 秒後到達」，可以得知什麼？',['會持續搖 13 秒','所有縣市都震度 4','劇烈搖晃前約有 13 秒避難','規模一定是 4'],2,'倒數秒數是主要震波到達前的預警時間，不是搖晃時長或地震規模。']
  ,'自然:神經系統與反應':['115 年國中教育會考｜自然第 10 題','聽到槍聲後起跑，判讀中樞神經示意圖時，哪一種工作最需由大腦負責？',['產生聽覺並作出隨意動作','只維持平衡','只調節心跳','只產生反射'],0,'感覺訊息的辨識與自主起跑要由大腦整合；題目要求連結構造位置與功能。']
  ,'自然:化學反應速率':['115 年國中教育會考｜自然第 12 題','比較不同濃度氫氧化鈉皂化反應，但只量到最終產物質量，能否判斷濃度與反應速率？',['可以，濃度加倍速率四倍','可以，先升後降','不行，濃度不同','不行，未記錄反應時間'],3,'反應速率需要「變化量／時間」；只有最後產物質量不能比較快慢。']
  ,'自然:遺傳與基因':['115 年國中教育會考｜自然第 13 題','人類以不同特徵玉米植株雜交育種，最合理的敘述是？',['無性生殖','有性生殖','親子表現型必相同','親子基因型必相同'],1,'雜交涉及生殖器官與配子結合，是有性生殖；子代會有遺傳組合差異。']
  ,'自然:天文與永續':['115 年國中教育會考｜自然第 14 題','連續觀察月相時，要推回前 7 天月相，最重要的規律是？',['月相每天完全相同','月相依週期逐日連續變化','月相只由天氣決定','月相和日地月位置無關'],1,'月相反映日、地、月相對位置，約一個月週期連續改變；官方題以連續觀測圖判讀。']
  ,'自然:聲音與波動':['114 年國中教育會考｜自然第 1 題','孕婦產檢使用超聲波時，通常聽不見它，最合理原因為何？',['音量太小','波速太快','頻率高於人耳可聽範圍','沒有介質'],2,'超聲波的頻率高於人耳可聽範圍；聽不見的關鍵是頻率，不是波速。']
  ,'自然:生態系與能量流動':['114 年國中教育會考｜自然第 3 題','白尾八哥與麻雀築巢位置、食物相似，且白尾八哥會吃麻雀幼鳥，兩者關係為何？',['競爭與掠食','競爭與共生','共生與掠食','寄生與掠食'],0,'使用相近資源形成競爭；捕食麻雀幼鳥則是掠食，兩種交互作用可同時存在。']
  ,'自然:探究自然的方法':['114 年國中教育會考｜自然第 7 題','要反駁「只有端午節正午才能立蛋」的說法，最合適的實驗是？',['端午節換熟蛋','聖誕節正午以同種生雞蛋成功立蛋','端午節改鴨蛋','端午節換另一種生雞蛋'],1,'要檢驗日期是否必要，應在其他條件盡量相同下改變日期；聖誕節仍能立蛋就是直接反例。']
  ,'自然:植物如何製造養分':['114 年國中教育會考｜自然第 8 題','蘆筍綠色部位受光、白色部位未受光。哪項氣體敘述最合理？',['綠色部位可釋出氧氣，白色部位不能','綠色部位可釋出二氧化碳，白色部位不能','白色部位可釋出氧氣，綠色部位不能','白色部位可釋出二氧化碳，綠色部位不能'],0,'受光且有葉綠體的綠色部位可行光合作用釋出氧氣；白色部位無法正常進行此作用。兩部位仍都會呼吸。']
  ,'自然:力與運動':['114 年國中教育會考｜自然第 9 題','鉛筆受左右兩水平力後靜止平衡，左端施力為 1 N。忽略摩擦時右端施力與兩端反作用力關係為何？',['右端反作用力小於右端施力且小於 1 N','右端反作用力小於右端施力且等於 1 N','右端反作用力等於右端施力但小於 1 N','右端反作用力等於右端施力且等於 1 N'],3,'靜力平衡使左右外力大小相等，右端施力也是 1 N；每一對作用力與反作用力大小相等，因此右端反作用力也為 1 N。']
  ,'自然:溫度與熱':['114 年國中教育會考｜自然第 26 題','比較鋁與銅的比熱，最合理的設計為何？',['同體積加熱，先熔化者比熱小','同體積加熱，升溫快者比熱小','同質量加熱，先熔化者比熱小','同質量加熱，升溫快者比熱小'],3,'比較比熱需控制質量與加熱條件；相同熱量下，溫度上升較快表示每升高 1°C 所需熱量較少，比熱較小。']
  ,'自然:遺傳與基因':['114 年國中教育會考｜自然第 30 題','兩隻黑眼孔雀魚交配後產生黑、紅兩種子代。可確定哪兩隻的基因型相同？',['兩親代','親代甲與任一黑眼子代','親代乙與任一黑眼子代','任兩隻黑眼子代'],0,'紅眼子代為 aa，表示兩個黑眼親代都必須各提供 a，因此兩親代皆為 Aa；黑眼子代則可能是 AA 或 Aa。']
  ,'自然:能源轉換':['114 年國中教育會考｜自然第 42 題','自行車發電共產生 0.021 kWh，電價每度 3 元，對應電費如何計算？',['700÷1000×3 元','0.021×3 元','0.021÷1000×700×3 元','0.021÷700×1000×3 元'],1,'一度電就是 1 kWh，因此費用＝0.021 kWh×3 元/kWh；不需再把功率 700 W 代入。']
};const row=data[key];return row?{kind:row[0],question:row[1],answers:row[2],correct:row[3],explanation:row[4],tip:'先讀題幹條件，再用圖、式或列舉法重建關係；官方題本的圖表必須連同標示一起判讀。'}:null;}
function guideConceptQuestions(lesson){const facts=window.CHAPTER_STUDY_GUIDES?.[lesson.subject]?.[lesson.unit];if(!facts)return [];const labels=['核心事實','模型推理','情境判讀','常見迷思'];const decoys=[
  ['只要背章名即可','可以忽略條件直接作答','所有題目都只靠猜測'],
  ['不需要建立圖、式或流程','可任意改變題目條件','不必檢查前後關係'],
  ['生活情境不必回到本節概念','只看一個關鍵字就能判定','結果不需要符合題目限制'],
  ['看到熟悉名詞就直接選','不必回到定義或證據','錯誤規則也可以套用']
];return facts.slice(0,4).map((fact,index)=>({kind:labels[index],question:`關於「${lesson.unit}」，下列哪一項敘述最符合本節重點？`,answers:[fact,...decoys[index]],correct:0,explanation:fact,tip:`回到本節的互動模型，找出題幹中的條件，再用「${labels[index]}」這一句話檢查選項；不能只憑關鍵字猜。`}));}
function chapterPracticeBank(lesson){
  const base={question:lesson.question,answers:lesson.answers,correct:lesson.correct,explanation:lesson.explanation,tip:solvingTip(lesson),kind:'核心概念'};
  const shared=[
    ['條件辨識',`面對「${lesson.unit}」的題目，第一步最應該做什麼？`,['只記住題名','標示題幹已知條件，對照本節模型','先看選項猜答案','跳過圖表或單位'],1,`本節的關鍵不是背題名，而是把條件放回「${lesson.key}」的關係中。`,solvingTip(lesson)],
    ['圖像判讀',`題目提供圖、表或流程時，最可靠的判讀方式是？`,['只看最醒目的顏色','先讀標題、標示、方向／單位，再連回${lesson.unit}','把圖當裝飾','用生活印象取代圖上的證據'],1,`圖像的標示、方向與單位都是作答依據；先讀它們才能避免望圖生義。`,solvingTip(lesson)],
    ['常見迷思',`下列何者最能避免「${lesson.unit}」的常見誤解？`,['只背結論','用反例或代回原條件驗證','只記答案位置','忽略題目的限制條件'],1,`能解釋、驗證與找反例，才表示真正理解本節概念。`,solvingTip(lesson)],
    ['生活情境',`生活中遇到和「${lesson.unit}」有關的現象，最合適的處理順序是？`,['先下結論','觀察資料→找條件→套用本節關係→檢查結果','只問別人的答案','先選一個看起來熟悉的名詞'],1,`會考情境題考的是把本節概念轉到新情境；需要先整理資料與關係。`,solvingTip(lesson)],
    ['證據檢查',`若兩個選項都看似合理，應如何決定？`,['選字最多的','選能完整符合題幹每一個條件的','選最熟悉的術語','隨機猜'],1,`逐條核對題幹條件，能排除只對一半或偷換概念的選項。`,solvingTip(lesson)],
    ['解題表達',`下列哪個答案最能顯示你理解「${lesson.unit}」？`,['只寫最後結論','說出條件、使用的關係和驗證理由','只寫一個名詞','只抄題目'],1,`能把條件、關係與驗證說完整，才是可檢查的理解。`,solvingTip(lesson)],
    ['變因轉換',`若題目改變一個條件，最先應檢查什麼？`,['答案選項順序','該條件在本節模型中影響哪一個量或步驟','題目字數','是否有熟悉關鍵字'],1,`先找改變的變因，再沿本節的因果或運算關係推結果。`,solvingTip(lesson)],
    ['素養應用',`「${lesson.unit}」的跨情境題要求學生做的核心能力是？`,['背誦原句','把概念模型套入新資料並說明理由','只找相同的題目','忽略資料來源'],1,`新情境的表面可以不同，但概念關係不變；先找出它和本節的對應。`,solvingTip(lesson)],
    ['自我檢核',`完成本節題目後，最好的自我檢查是？`,['立刻看下一題','用自己的話重述原理，並檢查答案是否符合條件','只看對錯','把錯誤遮起來'],1,`把原理說出來並回代條件，可分辨是真懂還是剛好猜對。`,solvingTip(lesson)]
  ];
  const guideRows=guideConceptQuestions(lesson);const rows=[base,...guideRows,...shared].slice(0,10); const application=lesson.subject==='數學'?mathApplicationQuestion(lesson.unit):lesson.subject==='自然'?scienceApplicationQuestion(lesson.unit):lesson.subject==='英文'?englishApplicationQuestion(lesson.unit):humanitiesApplicationQuestion(lesson.subject,lesson.unit), past=officialPastExamQuestion(lesson.subject,lesson.unit); if(application) rows[5]=application; if(past) rows[8]=past;
  return rows.map((row,index)=>({index,...(Array.isArray(row)?{kind:row[0],question:row[1],answers:row[2],correct:row[3],explanation:row[4],tip:row[5]}:row)}));
}
function chapterPracticeView(lesson){const items=chapterPracticeBank(lesson);return `<section class="question card chapter-practice"><div class="eyebrow">本節 10 題理解測驗</div><h2>每一題作答後都顯示原理與解題方法</h2><p>含「生活情境」與「素養應用」題；數學與自然題以模型、圖像或關係式來檢查，而不是只背答案。</p>${items.map(item=>`<article class="practice-item"><div class="eyebrow">第 ${item.index+1} 題｜${item.kind}</div><h3>${item.question}</h3><div class="answers">${item.answers.map((answer,i)=>`<button class="answer" data-chapter-practice-answer="${item.index}:${i}">${String.fromCharCode(65+i)}. ${answer}</button>`).join('')}</div><div class="practice-feedback" id="practiceFeedback${item.index}"></div></article>`).join('')}</section>`;}
function answerChapterPractice(index,choice){const lesson=state.lesson,item=chapterPracticeBank(lesson)[index],feedback=document.querySelector(`#practiceFeedback${index}`),buttons=document.querySelectorAll(`[data-chapter-practice-answer^="${index}:"]`);buttons.forEach(button=>{const selected=Number(button.dataset.chapterPracticeAnswer.split(':')[1]);button.classList.toggle('correct',selected===item.correct);button.classList.toggle('wrong',selected===choice&&choice!==item.correct);button.disabled=true;});feedback.innerHTML=`<div class="feedback"><b>${choice===item.correct?'答對了，也要知道為什麼。':'先別急著背，跟著方法看一次。'}</b><br><b>正確答案：</b>${String.fromCharCode(65+item.correct)}. ${item.answers[item.correct]}<br><b>觀念原理：</b>${item.explanation}<br><b>解題方法：</b>${item.tip}</div>`;}
function openChapter(value,updateUrl=true){const [grade,subject,no,title,goal]=value.split("|"),quiz=chapterQuiz(subject,title,goal);state.grade=+grade;state.subject=subject;state.lesson={title:`${no}｜${title}`,subject,unit:title,key:goal,...quiz,progressKey:`${grade}年級 ${subject}:${no} ${title}`,chapter:true};state.view="lesson";if(updateUrl)history.pushState(null,"",`#chapter=${encodeURIComponent(value)}`);render();}
function clearChapterRoute(){ if(location.hash) history.replaceState(null,"",`${location.pathname}${location.search}`); }
function goView(view){ clearChapterRoute(); state.view=view; state.lesson=null; render(); }
function bind(){ const brand=document.querySelector(".brand");if(brand)brand.onclick=event=>{event.preventDefault();goView("home");}; document.querySelectorAll(".nav-link").forEach(b=>b.onclick=()=>goView(b.dataset.view)); document.querySelectorAll("[data-subject]").forEach(b=>b.onclick=()=>{clearChapterRoute();state.subject=b.dataset.subject;state.view="courses";render();}); document.querySelectorAll("[data-grade]").forEach(b=>b.onclick=()=>{state.grade=+b.dataset.grade;render();}); document.querySelectorAll("[data-open]").forEach(b=>b.onclick=()=>openLesson(b.dataset.open)); document.querySelectorAll("[data-open-chapter]").forEach(b=>b.onclick=()=>openChapter(b.dataset.openChapter)); document.querySelectorAll("[data-action='courses']").forEach(b=>b.onclick=()=>goView("courses")); document.querySelector("#exportButton")?.addEventListener("click",exportData); document.querySelector("#noteArea")?.addEventListener("input",e=>{state.data.notes[state.lesson.key]=e.target.value;save();document.querySelector("#noteStatus").textContent="已自動儲存";}); document.querySelector("#completeButton")?.addEventListener("click",()=>{state.data.completed[state.lesson.key]=true;save();notify("太好了！已把這一節加入學習進度。");render();}); document.querySelectorAll("[data-answer]").forEach(b=>b.onclick=()=>answer(+b.dataset.answer)); document.querySelectorAll("[data-chapter-practice-answer]").forEach(b=>b.onclick=()=>{const [index,choice]=b.dataset.chapterPracticeAnswer.split(':').map(Number);answerChapterPractice(index,choice);}); bindVisual(); }
function solvingTip(lesson){ const tips={"自然":"先找出題目問的是『構造、現象還是原因』，再用流程圖追蹤變化；不要只靠名詞的字面意思猜答案。","數學":"先把題目的已知條件標在圖或式子上，再使用關係式逐步計算；最後把答案代回檢查是否合理。","社會":"先抓時間、地點與主題三個線索，再比較事件的先後與因果；不要只孤立地背年代或名詞。","國文":"先找作者的主張，再找能支持主張的理由或證據；選項若只是重複、無關或情緒化描述，通常不是答案。","英文":"先看句子要表達的時間與語意，再找對應的動詞形式；不要只憑看到熟悉單字就作答。"}; return lesson.tip || tips[lesson.subject]||"先圈出題目真正要問的概念，用自己的話說明理由，再回頭排除不符合條件的選項。"; }
function answer(choice){ const l=state.lesson,feedback=document.querySelector("#feedback"),correctAnswer=l.answers[l.correct];document.querySelectorAll(".answer").forEach((b,i)=>{b.classList.toggle("correct",i===l.correct);b.classList.toggle("wrong",i===choice&&i!==l.correct);}); state.data.answers[l.key]=choice;save();feedback.innerHTML=`<div class="feedback"><b>${choice===l.correct?"答對了，也要知道為什麼。":"這題先別急著背，跟著解題步驟看一次。"}</b><br><b>正確答案：</b>${String.fromCharCode(65+l.correct)}. ${correctAnswer}<br><b>觀念原理：</b>${l.explanation}<br><b>解題技巧：</b>${solvingTip(l)}</div>`; }
function bindVisual(){ document.querySelectorAll("[data-rotate]").forEach(b=>b.onclick=()=>{document.querySelector("#heartModel").style.transform=`rotateY(${b.dataset.rotate}deg) rotateX(-8deg)`;document.querySelectorAll("[data-rotate]").forEach(x=>x.classList.toggle("active",x===b));}); document.querySelectorAll("[data-part]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-part]").forEach(x=>x.classList.remove("selected"));b.classList.add("selected");document.querySelector("#partExplain").textContent=({"左心房":"左心房接收從肺部回流的含氧血。","右心房":"右心房接收從全身回流、含氧較少的血液。","左心室":"左心室將含氧血強力送入主動脈，前往全身。","右心室":"右心室將血液送往肺部進行氣體交換。","主動脈":"主動脈是將含氧血送往全身的大血管。","腔靜脈":"腔靜脈把全身回流的血液帶回右心房。"})[b.dataset.part];}); document.querySelector("[data-flow]")?.addEventListener("click",()=>{const d=document.querySelector(".flow-dot");d.style.animation="none";requestAnimationFrame(()=>d.style.animation="flow 3s infinite");notify("正在追蹤血液流動路徑");}); document.querySelector("#slope")?.addEventListener("input",e=>{const v=+e.target.value;document.querySelector("#slopeOut").value=v;document.querySelector("#functionLine").style.setProperty("--slope",`${-v*18}deg`);document.querySelector("#mathExplain").textContent=v===0?"斜率 = 0：這是一條水平線，y 不會隨 x 改變。":`斜率 = ${v}：x 每增加 1，y ${v>0?"增加":"減少"} ${Math.abs(v)}。`;}); let circuit="parallel",broken=false;document.querySelectorAll("[data-circuit]").forEach(b=>b.onclick=()=>{circuit=b.dataset.circuit;broken=false;document.querySelectorAll("[data-circuit]").forEach(x=>x.classList.toggle("active",x===b));document.querySelector("#bulbA").style.width="100%";document.querySelector("#bulbB").style.width="100%";document.querySelector("#labExplain").textContent=circuit==="parallel"?"並聯有不同支路，A 斷開時 B 仍然可以發亮。":"串聯只有一條路徑，任一處斷開會使整個電路中斷。";});document.querySelector("[data-break]")?.addEventListener("click",()=>{broken=true;document.querySelector("#bulbA").style.width="0%";document.querySelector("#bulbB").style.width=circuit==="series"?"0%":"100%";document.querySelector("#labExplain").textContent=circuit==="series"?"A 斷開後，電流無法形成完整迴路，B 也熄滅。":"A 的支路斷開，但 B 還有自己的路徑，因此仍亮著。";});document.querySelectorAll("[data-event]").forEach(b=>b.onclick=()=>{document.querySelectorAll(".event").forEach(x=>x.classList.toggle("active",x===b));const info=["清代治理臺灣：制度與移民活動影響臺灣社會發展。","工業革命：機械化生產與交通革新改變全球貿易。","臺灣開港：臺灣更直接進入世界貿易網絡。","甲午戰爭：東亞局勢改變，臺灣的統治者也隨之變動。","日治時期：現代制度與基礎建設帶來社會變化。"];document.querySelector("#timeExplain").textContent=info[+b.dataset.event];}); }
function exportData(){ const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),data:state.data},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="學習星圖備份.json";a.click();URL.revokeObjectURL(a.href);notify("備份檔已下載。"); }
document.querySelector("#backupButton").onclick=()=>{const choice=confirm("按「確定」匯出備份；按「取消」選擇備份檔匯入。");if(choice)exportData();else document.querySelector("#importInput").click();};document.querySelector("#importInput").onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const json=JSON.parse(await file.text());if(!json?.data?.notes||!json?.data?.completed)throw Error();if(!confirm("匯入將以備份檔取代目前的本機學習資料，是否繼續？"))return;state.data=json.data;save();notify("已成功匯入備份。");render();}catch{notify("這不是可用的學習星圖備份檔。 ");}e.target.value="";};
const savedChapter=new URLSearchParams(location.hash.replace(/^#/,'')).get('chapter');
if(savedChapter) openChapter(savedChapter,false); else render();
window.addEventListener('popstate',()=>{const chapter=new URLSearchParams(location.hash.replace(/^#/,'')).get('chapter');if(chapter)openChapter(chapter,false);else {state.view='home';state.lesson=null;render();}});

function examView(){ const scope=Object.entries(EXAM_SCOPE).map(([subject,items])=>`<section class="card scope-card"><div class="eyebrow">${subject}常見範圍</div><h2>${subject}</h2><ul class="scope-list">${items.map(item=>`<li>${item}</li>`).join("")}</ul></section>`).join(""); const archive=OFFICIAL_YEARS.map(year=>`<a class="chip" target="_blank" rel="noopener" href="https://cap.rcpet.edu.tw/exam/${year}/${year}exam.html">${year} 年官方題本</a>`).join(""); return `<section class="card exam-banner"><div class="eyebrow">跨學科素養練習</div><h1>會考連貫性挑戰</h1><p>先讀情境、整合不同科目的資料與概念，再作答。每題都會提供正解、原理與解題策略，不以背答案為目標。</p><div class="exam-progress">本回合共 ${MIXED_CHALLENGES.length} 題 · 涵蓋五科連貫能力</div><button class="secondary" id="startExam">開始本回合</button></section><div id="examArea"><section class="card scope-card"><div class="eyebrow">官方歷屆試題來源</div><h2>102–115 年國中教育會考題本</h2><p>題本與參考答案由國中教育會考官方網站提供。單元練習會以「年度、科目、題號、考點」標記；本站另撰寫解題方法與常見誤區。</p><div class="control-row">${archive}</div></section><div class="section-head"><div><div class="eyebrow">國中教育會考導向範圍</div><h2>五科主題總覽</h2></div></div>${scope}</div>`; }
function startExam(){ let index=0,score=0; const area=document.querySelector("#examArea"); const show=()=>{const item=MIXED_CHALLENGES[index];area.innerHTML=`<section class="card exam-question"><span class="subject-pill">${item.subject}</span><div class="eyebrow">第 ${index+1} / ${MIXED_CHALLENGES.length} 題</div><h3>${item.title}</h3><p>${item.prompt}</p><div class="answers">${item.answers.map((a,i)=>`<button class="answer" data-mixed-answer="${i}">${String.fromCharCode(65+i)}. ${a}</button>`).join("")}</div><div id="mixedFeedback"></div></section>`;document.querySelectorAll("[data-mixed-answer]").forEach(b=>b.onclick=()=>{const choice=+b.dataset.mixedAnswer,feedback=document.querySelector("#mixedFeedback");document.querySelectorAll("[data-mixed-answer]").forEach((x,i)=>{x.classList.toggle("correct",i===item.correct);x.classList.toggle("wrong",i===choice&&i!==item.correct);x.disabled=true;});if(choice===item.correct)score++;feedback.innerHTML=`<div class="feedback"><b>${choice===item.correct?"答對了！":"正確答案是："} ${String.fromCharCode(65+item.correct)}. ${item.answers[item.correct]}</b><br><b>連貫原理：</b>${item.reason}<br><b>解題策略：</b>${item.tip}</div><button class="primary" id="nextMixed">${index===MIXED_CHALLENGES.length-1?"查看結果":"下一題"}</button>`;document.querySelector("#nextMixed").onclick=()=>{index++;if(index<MIXED_CHALLENGES.length)show();else area.innerHTML=`<section class="card exam-result"><h2>本回合完成：${score} / ${MIXED_CHALLENGES.length}</h2><p>答錯的題目不是扣分紀錄，而是下一次複習的路標。回到課程地圖，把相關單元用自己的話重述一次，再重做這回挑戰。</p><button class="primary" id="retryExam">再挑戰一次</button></section>`;document.querySelector("#retryExam")?.addEventListener("click",startExam);};});};show(); }
document.addEventListener("click",event=>{ if(event.target.closest("#startExam")) startExam(); });
